import { Component, OnInit, ViewChild, ElementRef } from '@angular/core';
import { VozackaService } from '../services/vozacka.service';
import { VozackaDozvola } from '../models/vozacka-dozvola.model';
import { NgForm } from '@angular/forms';

@Component({
  selector: 'app-vozacka',
  templateUrl: './vozacka.component.html',
  styleUrls: ['./vozacka.component.css']
})
export class VozackaComponent implements OnInit {

  @ViewChild('vozackaModal') vozackaModal!: ElementRef;

  vozacke: VozackaDozvola[] = [];
  showAlert: boolean = false;
  alertMessage: string = '';
  alertType: 'success' | 'danger' = 'success';

  noviZahtev: any = {
    grad: '',
    kategorijeStr: '' // korisnik unosi kao string "A,B,C"
  };

  isEmployer: boolean = false;      // da li je korisnik admin/poslodavac
  imaAktivanZahtev: boolean = false; // proverava da li postoji aktivan zahtev

  constructor(private vozackaService: VozackaService) { }

  ngOnInit(): void {
    this.ucitajVozacke();
    this.proveriUlogu();
  }

  // Učitavanje svih vozačkih dozvola korisnika
  ucitajVozacke(): void {
    this.vozackaService.dohvatiSve().subscribe({
      next: (res: VozackaDozvola[]) => {
        this.vozacke = res;
        this.imaAktivanZahtev = this.vozacke.some(v => v.status === 'CEKANJE');
      },
      error: (err) => this.prikaziAlert('Greška pri učitavanju vozačkih dozvola', 'danger')
    });
  }

  // Otvaranje modala za podnošenje zahteva
  openVozackaModal(): void {
    const modalEl = this.vozackaModal.nativeElement;
    const modal = new window.bootstrap.Modal(modalEl);
    modal.show();
  }

  // Podnošenje novog zahteva
  podnesiZahtev(form: NgForm): void {
    if (form.invalid) return;

    const kategorijeArray = this.noviZahtev.kategorijeStr.split(',')
      .map((k: string) => k.trim())
      .filter((k: string) => k.length > 0);

    const zahtevPayload = {
      grad: this.noviZahtev.grad,
      kategorije: kategorijeArray
    };

    this.vozackaService.podnesiZahtev(zahtevPayload).subscribe({
      next: (res) => {
        this.prikaziAlert('Zahtev za vozačku dozvolu je uspešno podnet!', 'success');
        this.ucitajVozacke();
        form.resetForm();
        // Zatvori modal
        const modalEl = this.vozackaModal.nativeElement;
        const modal = window.bootstrap.Modal.getInstance(modalEl);
        modal.hide();
      },
      error: (err) => this.prikaziAlert(err.error || 'Greška prilikom podnošenja zahteva', 'danger')
    });
  }

  // Prikaz alert poruke
  prikaziAlert(message: string, type: 'success' | 'danger'): void {
    this.alertMessage = message;
    this.alertType = type;
    this.showAlert = true;
    setTimeout(() => this.showAlert = false, 5000);
  }

  closeAlert(): void {
    this.showAlert = false;
  }

  // Provera uloge korisnika (primer, može se dohvatiti iz tokena)
  proveriUlogu(): void {
    this.isEmployer = this.vozackaService.proveriDaLiJeEmployer();
  }
}
